#!/usr/bin/env python3
"""Ролик №5 «Заработок на кредитке: проверил схему на цифрах (2026)» — таймлайн в стиле «Премиум» v2 (modes/premium.js) по словам голоса.
Устроен как build4.py ролика №4 (фоны по кругу, переходы по кругу, пульсы на началах предложений).
  python3 build5.py [voice/words.json]   → timeline5.js + video5.html
  python3 build5.py draft                → черновые слова из voice/phrases.txt (189 сл/мин) → out/draft_words.json
Суммы на экране — пример из расчётов script.md (условия на 13.10.2026).
"""
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, "../kit/yt")); sys.path.insert(0, os.path.join(HERE, "../kit"))
from build import Build
from anchors import norm

if sys.argv[1:2] == ["draft"]:
    ws, t, step = [], .3, 60 / 189
    sec = [l.strip() for l in open(os.path.join(HERE, "voice/sections.txt"))]
    for i, p in enumerate(l.strip() for l in open(os.path.join(HERE, "voice/phrases.txt"))):
        if i and sec[i] != sec[i - 1]: t += .9
        for w in p.split():
            if not norm(w): continue
            ws.append({"w": w, "a": round(t, 3), "d": round(step * .85, 3)}); t += step
        t += .4
    os.makedirs(os.path.join(HERE, "out"), exist_ok=True)
    json.dump({"duration": round(t, 3), "words": ws, "draft": True}, open(os.path.join(HERE, "out/draft_words.json"), "w"), ensure_ascii=False)
    print(f"черновые слова: {len(ws)}, {t / 60:.1f} мин"); sys.exit()

