_tl = B.timeline
def _tl_pulses():
    tl = _tl(); ws = B.W.ws
    starts = [ws[i]["a"] - tl["base"] for i in range(len(ws)) if i == 0 or ws[i - 1]["w"][-1] in ".!?…:"]
    for s in tl["segs"]: s["data"]["pulses"] = [round(x - s["t0"], 3) for x in starts if s["t0"] + .8 < x < s["t1"] - .3]
    return tl
B.timeline = _tl_pulses
B.write(os.path.join(HERE, "timeline5.js"), page=os.path.join(HERE, "video5.html"))
